import {architectureView,caseArchitecture} from './architecture.js?v=20260918-topology';
import {caseDeployment} from './company-playbooks.js';
import {vendorPage,installVendorEvents,lenaGuide} from './vendor.js?v=20260920-review1';
import {franchisePage,installFranchiseEvents,mayaGuide} from './franchise.js?v=20260920-review1';
import {loyaltyPage,installLoyaltyEvents,elenaGuide} from './loyalty.js?v=20260920-loyalty2';
import {aiContent} from './ai-guide.js?v=20260919-aistage4';
import {homePage} from './home.js?v=20260920-loyalty2';
import {userMoments,userLinks,userAccount} from './perspectives.js';
import {buildDemoGuide} from './demo-guide.js';
import {createRemoteSession} from './remote-session.js?v=20260919-aistage4';
import {remoteConfig} from './remote-config.js';
import {journeyProgress,wholeJourney,externalIdLens} from './journey-narrative.js?v=20260920-external-lens1';
import {people,URLS,SOURCE,AGENTS} from './data.js';
import {agenda,cases} from './workshop.js';
const app=document.getElementById('app');
const remote=createRemoteSession();
const icons={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6"/>',play:'<path d="m8 5 11 7-11 7z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',screen:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M12 16v5m-5 0h10"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',left:'<path d="M19 12H5m5-5-5 5 5 5"/>',signal:'<path d="M3 12h4l3-8 4 16 3-8h4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={person:0,moment:0,tab:'story',present:false,home:true,vendor:false,franchise:false,loyalty:false,vendorView:'experience',franchiseView:'experience',loyaltyView:'experience'};
const presenter=new URLSearchParams(location.search).get('view')==='presenter';
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('harborline-workshop-v1'):null;
const tabs=[['story','The story'],['architecture','Architecture'],['setup','Admin view'],['user','User view'],['live','Live demo'],['evidence','Evidence'],['ai','How AI helps']];
function readHash(){const bits=location.hash.slice(1).split('/');state.vendor=bits[0]==='lena';state.franchise=bits[0]==='maya';state.loyalty=bits[0]==='elena';state.vendorView=['experience','explain','prove'].includes(bits[1])?bits[1]:'experience';state.franchiseView=['experience','architecture','evidence'].includes(bits[1])?bits[1]:'experience';state.loyaltyView=['experience','architecture','evidence'].includes(bits[1])?bits[1]:'experience';const i=people.findIndex(p=>p.id===bits[0]);state.home=i<0&&!state.vendor&&!state.franchise&&!state.loyalty;if(i>=0){state.person=i;state.moment=Math.min(Math.max(0,(Number(bits[1])||1)-1),people[i].moments.length-1);state.tab=tabs.some(t=>t[0]===bits[2])?bits[2]:'story';}}
readHash();
const palette=['#20f593','#b98aff','#68e9cb','#d5aeff','#8ccfff','#a6eaa1'];
const tabIcons={story:'signal',architecture:'grid',setup:'grid',user:'screen',live:'play',evidence:'signal',ai:'arrow'};
const person=()=>people[state.person],moment=()=>person().moments[state.moment];
function link(label,url,desc=''){return `<a class="launch" href="${escape(URLS[url]||url)}" target="_blank" rel="noopener noreferrer"><span>${escape(label)}${desc?`<small>${escape(desc)}</small>`:''}</span>${icon('external')}</a>`;}
function mainContent(){const p=person(),m=moment();if(state.tab==='architecture')return architectureView(p,m,state.architectureStep||0)+externalIdLens(p,'architecture');
if(state.tab==='setup')return `<div class="perspective-banner"><span class="pill">Admin view</span><span>Harborline administrator · verify the tenant and role</span></div><div class="two-col"><div><div class="eyebrow">Configure and verify</div><ol class="steps">${m.setup.map(s=>`<li>${escape(s)}</li>`).join('')}</ol><div class="perspective-actions"><button class="primary" data-action="remote">Open admin workspace ${icon('screen')}</button><button class="outline" data-action="tab" data-value="user">Show the user experience ${icon('arrow')}</button></div></div><div><div class="eyebrow">Admin portals</div><div class="launch-list">${(m.links.filter(l=>!userLinks.some(u=>u[1]===l[1])).length?m.links.filter(l=>!userLinks.some(u=>u[1]===l[1])):[['Inspect user and assignments','users'],['Inspect authentication policy','methods']]).map(l=>link(...l)).join('')}</div><p class="source-caption">Use your administrator browser profile. These shortcuts open on this computer; use the remote browser for the embedded demonstration.</p><div class="note">${escape(m.evidence)}</div></div></div>`;
if(state.tab==='user'){const u=userMoments[p.id][state.moment];return `<div class="perspective-banner user"><span class="pill">User view</span><span>${escape(p.name)} · ${escape(userAccount(p))}</span></div><div class="two-col"><div><div class="eyebrow">Experience the working day</div><h3 class="content-title">${escape(u[0])}</h3><ol class="steps">${u.slice(1).map(x=>`<li>${escape(x)}</li>`).join('')}</ol><div class="perspective-actions"><button class="primary" data-action="remote">Open user workspace ${icon('screen')}</button><button class="outline" data-action="tab" data-value="setup">See the admin controls ${icon('arrow')}</button></div></div><div><div class="eyebrow">User portals</div><div class="launch-list">${userLinks.map(l=>link(...l)).join('')}</div><div class="note">Use a separate browser profile for this persona. Check the signed-in account before presenting. Choosing User view does not switch Microsoft accounts.</div><p class="source-caption">Shortcuts open on this computer. In the embedded desktop, open the same portal in the persona’s browser profile. Live results still require the protected gateway and sign-in.</p></div></div>`;}
if(state.tab==='live')return `<div class="two-col"><div class="remote-launch-card"><div class="eyebrow">Real Microsoft Entra</div><h3>Two sides of the same story.</h3><div class="perspective-actions"><button class="outline" data-action="tab" data-value="setup">Admin view</button><button class="outline" data-action="tab" data-value="user">User view</button></div><p>Use the browser on your protected demo desktop. Click, navigate and expand the same session to full screen when you need room.</p><button class="primary" data-action="remote">Open Entra workspace ${icon('screen')}</button><small>${remote.configured()?'Presenter sign-in required.':'Gateway setup pending · fullscreen stage available.'}</small></div><div><div class="eyebrow">${escape(p.name)} · this moment</div><div class="note tenant-record" style="margin-top:12px"><strong>${escape(p.name)} · connected-tenant record</strong><br>Search by display name, then verify the object ID and signed-in tenant before making a change.<small>Story identifier · ${escape(p.account)}</small></div><div class="launch-list">${m.links.map(l=>link(...l)).join('')}</div><p class="source-caption">Portal shortcuts open on this computer. Inside the remote desktop, navigate with its own browser.</p><button class="outline" data-action="tab" data-value="evidence">What should I verify? ${icon('arrow')}</button></div></div>`;
if(state.tab==='evidence')return `<div class="two-col"><div><div class="eyebrow">What the demonstration needs to prove</div><h3 class="content-title" style="margin-top:12px">Observe the outcome.</h3><p class="content-copy">${escape(m.evidence)}</p><div class="question">${escape(p.question)}</div></div><div class="note amber"><strong>Know the boundary</strong><br>${escape(p.caution)}</div></div>`;
if(state.tab==='ai')return aiContent(p,m,state.moment);
return wholeJourney(p);
}
function render(){if(presenter){renderPresenter();return;}if(state.vendor){app.innerHTML=vendorPage(state.vendorView);return;}if(state.franchise){app.innerHTML=franchisePage(state.franchiseView);return;}if(state.loyalty){app.innerHTML=loyaltyPage(state.loyaltyView);return;}if(state.home){app.innerHTML=homePage();return;}const p=person(),m=moment();app.innerHTML=`<div class="shell" data-person="${p.id}" style="--accent:${palette[state.person]}"><div class="experience ${state.present?'presentation':''} tab-${state.tab}"><header class="topbar"><a class="brand" href="#home"><img class="majorkey-logo" src="./assets/majorkey-logo.svg" alt="MajorKey" width="220" height="38"><span class="brand-divider"></span><span class="brand-context">Identity in action<small>HARBORLINE WORKSHOP</small></span></a><div class="top-actions"><button class="quiet" data-action="agenda">${icon('clock')} Workshop agenda</button><button class="quiet optional" data-action="presenter">${icon('screen')} Presenter notes</button><button class="outline" data-action="home">Choose a persona</button><button class="outline" data-action="present">${icon('play')} ${state.present?'Exit presentation':'Present'}</button></div></header><div class="workspace"><aside class="sidebar"><div class="side-title"><div class="eyebrow">THE EXPERIENCE</div><h2>A day<br>in the life<span>.</span></h2><p>Six people. One connected story.</p></div><nav class="person-list" aria-label="Choose a person">${people.map((x,i)=>`<button class="person ${i===state.person?'active':''}" data-action="person" data-value="${i}" ${i===state.person?'aria-current="step"':''}><span class="avatar" style="--person-color:${palette[i]}">${x.initials}</span><span><strong>${x.name}</strong><small>${x.role}</small></span>${i===state.person?`<span class="person-arrow">${icon('arrow')}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="quiet" data-action="catalog">${icon('grid')} All 34 use cases</button><button class="quiet" data-action="ready">${icon('screen')} Before the room arrives</button><p>Harborline reference lab<br>Synthetic people. Real tenant setup.</p></div></aside><main class="main" id="main"><div class="chapterline"><span><span class="chapter-num">0${state.person+1} / 06</span> ${escape(p.role)}</span><button class="reference" data-action="agenda">${icon("clock")} 8-hour workshop</button></div><section class="story-top"><div class="chapter-intro"><div class="hero-kicker"><span>IDENTITY, THROUGH THEIR EYES</span><span>CHAPTER 0${state.person+1}</span></div><h1>${p.headline}</h1><p>${escape(p.intro)}</p></div><div class="person-card"><div class="identity-card-top"><span>HARBORLINE</span><span>0${state.person+1}</span></div><div class="identity-orbit" aria-hidden="true"><i></i><i></i><i></i></div><div class="identity-monogram" aria-hidden="true">${p.initials}</div><div class="identity-card-bottom"><div><div class="eyebrow">Meet the person</div><h2>${escape(p.name)}</h2><p>${escape(p.job)}</p></div><span class="persona-tag">${p.cases.length}<small>use cases</small></span></div><div class="identity-context"><span>${escape(p.company)}</span><span class="card-edition">PERSONA / 0${state.person+1}</span></div></div></section><section class="stage" aria-label="Current story moment"><div class="stage-top"><div><div class="eyebrow">${escape(p.name)}</div><h2>${state.tab==='story'?'The complete journey':escape(m.short)}</h2></div><button class="quiet" data-action="related">Related use cases ${icon('arrow')}</button></div>${state.tab==='story'?'':journeyProgress(p,state.moment)}<div class="tabs" role="tablist" aria-label="Explore this moment">${tabs.filter(([id])=>['story','architecture','live','ai'].includes(id)).map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" role="tab" id="tab-${id}" aria-selected="${state.tab===id}" aria-controls="panel" tabindex="${state.tab===id||(id==='story'&&!['story','architecture','live','ai'].includes(state.tab))||(id==='setup'&&!['setup','user','evidence'].includes(state.tab))?'0':'-1'}" data-action="tab" data-value="${id}">${id==='ai'?'<span class="ai-tab-spark" aria-hidden="true">✦</span>':`<span class="step-number">${['story','architecture','live'].indexOf(id)+2}</span>`}<span>${label}</span></button>`).join('')}</div><details class="supporting-tabs" ${['setup','user','evidence'].includes(state.tab)?'open':''}><summary>Explore more · admin, user &amp; evidence</summary><button class="quiet" data-action="presenter">Open presenter notes ↗</button><div class="tabs" role="tablist" aria-label="Supporting views">${tabs.filter(([id])=>['setup','user','evidence'].includes(id)).map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" role="tab" id="tab-${id}" aria-selected="${state.tab===id}" aria-controls="panel" tabindex="${state.tab===id||(id==='story'&&!['story','architecture','live','ai'].includes(state.tab))||(id==='setup'&&!['setup','user','evidence'].includes(state.tab))?'0':'-1'}" data-action="tab" data-value="${id}">${label}</button>`).join('')}</div></details><div id="panel" class="stage-content" role="tabpanel" tabindex="0" aria-labelledby="tab-${state.tab}">${mainContent()}</div>${state.tab==='story'||state.tab==='architecture'?`<div class="journey-next"><span>${state.tab==='story'?'Next: see how the identity controls connect.':'Next: explore the configuration and user experience in your tenant.'}</span><button class="primary" data-action="tab" data-value="${state.tab==='story'?'architecture':'live'}">${state.tab==='story'?'Continue to architecture':'Continue to live demo'} ${icon('arrow')}</button></div>`:''}${state.tab==='story'?`<div class="stage-footer whole-story-footer"><button class="quiet" data-action="person" data-value="${Math.max(0,state.person-1)}" ${state.person===0?'disabled':''}>${icon('left')} Previous person</button><span>Complete journey · ${escape(p.name)}</span><button class="quiet" data-action="${state.person===people.length-1?'home':'person'}" ${state.person===people.length-1?'':`data-value="${state.person+1}"`}>${state.person===people.length-1?'Choose another journey':'Next person'} ${icon('arrow')}</button></div>`:`<div class="stage-footer"><button class="quiet" data-action="prev" ${state.person===0&&state.moment===0?'disabled':''}>${icon('left')} Previous</button><span>${state.moment+1} of ${p.moments.length} moments · ${escape(p.name.split(' ')[0])}’s story</span><button class="quiet" data-action="next">${state.moment===p.moments.length-1?(state.person===people.length-1?'Workshop close':'Next person'):'Next moment'} ${icon('arrow')}</button></div>`}</section><footer class="bottomline"><span class="footer-brand"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="110" height="19"><span>Identity in action · Harborline reference lab</span></span><a href="${SOURCE}" target="_blank" rel="noopener noreferrer">Source hub ↗</a></footer></main></div></div></div><dialog id="modal" aria-labelledby="modal-title"></dialog>`;remote.setContext(p.name,m.short,state.tab==='user'?'User view':'Admin view',state.tab==='user'?userAccount(p):'Harborline administrator');remote.setGuide(buildDemoGuide(p,state.moment,state.tab==='user')); }
function update(){const hash=state.vendor?`#lena/${state.vendorView}`:state.franchise?`#maya/${state.franchiseView}`:state.loyalty?`#elena/${state.loyaltyView}`:state.home?'#home':`#${person().id}/${state.moment+1}/${state.tab}`;history.replaceState(null,'',hash);render();channel?.postMessage({type:'state',state});}
function move(dir){const p=person();if(dir>0){if(state.moment<p.moments.length-1)state.moment++;else if(state.person<people.length-1){state.person++;state.moment=0;}else {openModal('The day ends. The decisions begin.','<p class="content-copy">For each story, agree what matters in your environment, who owns the next action, and what evidence will prove it works.</p><ol class="steps">'+people.map(p=>`<li><span><strong>${p.name}</strong><br>${p.question}</span></li>`).join('')+'</ol>');return;}}else if(state.moment>0)state.moment--;else if(state.person>0){state.person--;state.moment=person().moments.length-1;}state.tab='story';update();}
function openModal(title,body){const d=document.getElementById('modal');d.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="quiet" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;d.showModal();}
function renderPresenter(){app.innerHTML=`<main class="presenter-layout"><div class="eyebrow">Presenter notes · keep this window off the shared screen</div><h1>${person().name}<br><span style="color:var(--accent)">${moment().title}</span></h1><p class="content-copy" id="sync-status">Follows the workshop when both windows are open on this device.</p><blockquote>${escape(person().talk)}</blockquote><div class="two-col"><section><h2 class="content-title">Show this</h2><ol class="steps">${moment().setup.map(s=>`<li>${escape(s)}</li>`).join('')}</ol></section><section><h2 class="content-title">Verify this</h2><p class="content-copy">${escape(moment().evidence)}</p></section></div><div class="note amber"><strong>Keep this distinction clear</strong><br>${escape(person().caution)}</div><div class="question">${escape(person().question)}</div><div class="controls"><a class="outline" href="./#${person().id}/${state.moment+1}/story" target="_blank" rel="noopener">Open audience view ${icon('external')}</a></div></main>`;}
channel?.addEventListener('message',e=>{if(e.data?.type==='request'&&!presenter)channel.postMessage({type:'state',state});if(e.data?.type==='state'&&presenter){state=e.data.state;renderPresenter();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;if(a==='start-demo'){state.vendor=false;state.franchise=false;state.loyalty=false;state.home=false;state.person=0;state.moment=0;state.tab='story';state.present=true;state.architectureStep=0;update();window.scrollTo(0,0);}if(a==='architecture-node'){state.architectureStep=Number(v);update();document.querySelector(`[data-action="architecture-node"][data-value="${v}"]`)?.focus();}if(a==='person-ai'){state.home=false;state.person=Number(v);state.moment=0;state.tab='ai';update();}if(a==='home'){state.vendor=false;state.franchise=false;state.loyalty=false;state.home=true;state.present=false;update();}if(a==='person'){state.home=false;state.person=Number(v);state.moment=0;state.tab='story';update();document.getElementById('main')?.scrollIntoView({block:'start'});}if(a==='moment'){state.moment=Number(v);state.tab='story';update();}if(a==='tab'){state.tab=v;update();document.getElementById(`tab-${v}`)?.focus();}if(a==='next')move(1);if(a==='prev')move(-1);if(a==='present'){state.present=!state.present;update();}if(a==='presenter'){const w=window.open(`./?view=presenter#${person().id}/${state.moment+1}/${state.tab}`,'harborline-presenter','popup,width=1050,height=800');if(!w)openModal('Presenter notes','<p>Your browser blocked the notes window. Allow pop-ups for this site, or open the link below in a separate window.</p>'+link('Open presenter notes',`./?view=presenter#${person().id}/${state.moment+1}/${state.tab}`));}if(a==='close')document.getElementById('modal').close();if(a==='agenda')openAgenda();if(a==='catalog'||a==='related')openCatalog(a==='related');if(a==='ready')openReady();if(a==='readiness-check')runReadiness();if(a==='remote')remote.open();});
document.addEventListener('keydown',e=>{if(!remote.isOpen()&&e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const group=[...e.target.closest('[role="tablist"]').querySelectorAll('[data-action="tab"]')].map(b=>b.dataset.value);let i=group.indexOf(state.tab);i=e.key==='Home'?0:e.key==='End'?group.length-1:(i+(e.key==='ArrowRight'?1:-1)+group.length)%group.length;state.tab=group[i];update();document.getElementById(`tab-${state.tab}`).focus();}if(!remote.isOpen()&&state.present&&!document.querySelector('dialog[open]')&&!e.target.closest('input,textarea,select,.arch-studio,[role="tab"]')){if(e.key==='ArrowRight'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}if(e.key==='Escape'){state.present=false;update();}}});
window.addEventListener('hashchange',()=>{readHash();update();});
document.addEventListener('workshop-lab-navigate',e=>{state.home=false;state.person=e.detail.personIndex;state.moment=e.detail.momentIndex;update();});
function openAgenda(){openModal('One day. Six human stories.',`<div class="label-row"><span class="pill green">09:00–17:00 · 8 hours</span><span class="pill">6 people · 34 reference use cases</span></div><p class="content-copy">Suggested running order, including lunch and breaks. Click a person’s chapter to jump into the story. Use each block for the human problem, configuration, live proof and client discussion.</p>${agenda.map(a=>`<div class="agenda-row"><span class="time">${a.time}<br><span style="color:var(--muted)">${a.end}</span></span><div>${a.person!==undefined?`<button data-action="person" data-value="${a.person}"><strong>${escape(a.title)} ↗</strong></button>`:`<strong>${escape(a.title)}</strong>`}<p>${escape(a.detail)}</p></div><small>${a.minutes} min</small></div>`).join('')}<div class="note" style="margin-top:24px"><strong>Let the client shape the depth.</strong><br>The library keeps every use case within reach. Use the story chapters as the backbone and open a specific case when a question needs a deeper answer.</div>`);}
let relatedOnly=false;
function catalogRows(query=''){const q=query.toLowerCase();const selected=cases.filter(c=>(!relatedOnly||person().cases.includes(c.id))&&`${c.id} ${c.title} ${c.category} ${c.description}`.toLowerCase().includes(q));return `<div class="catalog-result" role="status">${selected.length} use cases${relatedOnly?` connected to ${escape(person().name)}`:''}</div>${selected.map(c=>`<div class="catalog-row"><span>${String(c.id).padStart(2,'0')}</span><div><button class="case-title" data-action="case" data-value="${c.id}">${escape(c.title)} ${icon('arrow')}</button><p>${escape(c.category)}</p></div><span class="pill ${c.id===21||c.id===22?'amber':''}">${c.status}</span></div>`).join('')}${selected.length?'':'<p class="content-copy">No matching use cases. Try a person, system or a shorter phrase.</p>'}`;}
function openCatalog(related=false){relatedOnly=related;openModal(related?`${person().name} · connected use cases`:'All 34 reference use cases',`<p class="content-copy">Source-reported configuration from the Harborline hub, dated 17 September 2026. “Built” describes the source status; verify current behavior in the tenant.</p><label for="case-search" class="eyebrow">Find a use case</label><input class="search" id="case-search" type="search" placeholder="Search authentication, kiosk, claims…" autocomplete="off"><div id="catalog-results">${catalogRows()}</div>`);}
function openCase(id){const c=cases.find(c=>c.id===id);if(!c)return;const associated=people.map((p,i)=>({p,i})).filter(({p})=>p.cases.includes(id));openModal(`Use case ${c.id}`,`<div class="eyebrow">${escape(c.category)}</div><h3 class="content-title" style="margin-top:12px;font-size:29px">${escape(c.title)}</h3><div class="label-row"><span class="pill ${[21,22].includes(id)?'amber':''}">${c.status}</span><span class="pill">Reference · 17 Sep 2026</span></div><p class="content-copy">${escape(c.description)}</p>${caseArchitecture(c.id)}${caseDeployment(c.id)}<div class="two-col"><section><h4 class="eyebrow">Take it into the lab</h4>${link('Open the relevant portal',c.target,'Verify the selected tenant and named configuration.')}${link('Open full reference instructions',SOURCE,'Select use case '+c.id+' in the source hub.')}</section><section><h4 class="eyebrow">Connected human stories</h4>${associated.length?associated.map(({p,i})=>`<button class="launch" style="width:100%;margin-bottom:10px;text-align:left" data-action="person" data-value="${i}"><span>${escape(p.name)}<small>${escape(p.role)}</small></span>${icon('arrow')}</button>`).join(''):'<p class="content-copy">This is an architecture or external-identity extension. Use it during the relevant client discussion; the source hub contains its full demonstration.</p>'}</section></div><div class="note" style="margin-top:22px">${[21,22].includes(id)?'The source has the configuration. The full out-of-box experience still requires an eligible demonstration device.':'Inspect configuration, run the intended demonstration, then verify its evidence. A source status does not establish that an action executed or a policy is enforced.'}</div><button class="quiet" style="margin-top:20px" data-action="catalog">${icon('left')} Back to all use cases</button>`);}
function readinessRow(id,label,detail){return `<div class="readiness-row" data-check="${id}"><span class="readiness-dot" aria-hidden="true"></span><span><strong>${label}</strong><small>${detail}</small></span><b>Not checked</b></div>`;}
async function probeReadiness(id,url){const row=document.querySelector(`[data-check="${id}"]`);if(!row)return;row.className='readiness-row checking';row.querySelector('b').textContent='Checking…';const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),7000);try{await fetch(url,{mode:id==='workshop'?'same-origin':'no-cors',cache:'no-store',signal:controller.signal});row.className='readiness-row pass';row.querySelector('b').textContent=id==='workshop'?'Ready':'Reachable';}catch{row.className='readiness-row fail';row.querySelector('b').textContent='Needs attention';}finally{clearTimeout(timeout);}}
async function runReadiness(){const button=document.querySelector('[data-action="readiness-check"]');if(button){button.disabled=true;button.textContent='Running checks…';}const gateway=new URL(remoteConfig.gatewayUrl).origin+'/guacamole/';await Promise.all([probeReadiness('workshop','./'),probeReadiness('gateway',gateway),probeReadiness('agents',AGENTS)]);const browserRow=document.querySelector('[data-check="browser"]');if(browserRow){const ready=Boolean(document.fullscreenEnabled&&window.BroadcastChannel);browserRow.className=`readiness-row ${ready?'pass':'fail'}`;browserRow.querySelector('b').textContent=ready?'Ready':'Needs attention';}const stamp=document.getElementById('readiness-stamp');if(stamp)stamp.textContent=`Last checked ${new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}. Reachable confirms a network path; complete the manual proof below.`;if(button){button.disabled=false;button.textContent='Run live checks again';}}
function openReady(){const notes=`./?view=presenter#${person().id}/${state.moment+1}/${state.tab}`;openModal('Before the room arrives',`<div class="readiness-hero"><div><div class="eyebrow">Onsite control room</div><h3>Know the room is ready before the audience arrives.</h3><p>Run the network checks, then complete the tenant proof from the same laptop, network and display you will use onsite.</p></div><button class="primary" data-action="readiness-check">Run live checks</button></div><div class="readiness-grid">${readinessRow('workshop','Workshop stage','Public site and presentation assets')}${readinessRow('gateway','Protected desktops','Apache Guacamole network path')}${readinessRow('agents','Identity Agents','Live AI action service network path')}${readinessRow('browser','Presentation browser','Fullscreen and presenter synchronization')}</div><p class="source-caption" id="readiness-stamp">Checks have not run in this browser.</p><div class="two-col readiness-manual"><section><h3 class="content-title">Must-pass live proof</h3><ol class="steps"><li>Connect to both admin and user desktops and type into each session.</li><li>Open Entra in the admin desktop and confirm the intended tenant and account.</li><li>Sign in to Identity Agents inside the AI panel.</li><li>Run Add, Verify, Undo, then confirm Jordan is no longer in ZZ-DEMO-AI-Replay.</li><li>Check all six story accounts, dates, assignments and starting states.</li></ol></section><section><h3 class="content-title">Room and recovery</h3><ol class="steps"><li>Test the projector at 1920 × 1080 and confirm the audience can read the smallest labels.</li><li>Keep the presenter notes on your private screen; share only the audience window.</li><li>Bring power, HDMI/USB-C adapters and a tested backup hotspot.</li><li>Start the frontline and kiosk VMs before the session.</li><li>If a live service fails, move to Architecture and narrate the same control path honestly.</li></ol></section></div><div class="note amber"><strong>Final reset matters</strong><br>The isolated group ZZ-DEMO-AI-Replay should not contain the demo user before the workshop. Never expose passwords, tenant secrets or private run-sheet details on the shared screen.</div><div class="readiness-actions"><a class="outline" href="${notes}" target="_blank" rel="noopener">Open presenter notes in a normal tab ${icon('external')}</a>${link('Open the Entra admin center','users')}${link('Open your live agents',AGENTS)}</div>`);}
document.addEventListener('input',e=>{if(e.target.id==='case-search')document.getElementById('catalog-results').innerHTML=catalogRows(e.target.value);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="case"]');if(b)openCase(Number(b.dataset.value));});
installVendorEvents(render,()=>{remote.setContext('Lena Fischer','Vendor portal','User view','Prepared Lena account in the external tenant');remote.setGuide(lenaGuide());remote.open();});
installFranchiseEvents(render,()=>{remote.setContext('Maya Chen','Franchise portal','Owner view','Prepared Maya account in the external tenant');remote.setGuide(mayaGuide());remote.open();});
installLoyaltyEvents(render,()=>{remote.setContext('Elena Torres','Rewards portal','Customer view','Prepared Elena account in the external tenant');remote.setGuide(elenaGuide());remote.open();});
render();if(presenter)channel?.postMessage({type:'request'});
